"· I campi dal migliore al peggiore per costo unitario dei prodotti, rapportato al prezzo di mercato (i prodotti sono diversi). Il colore del campo è la coltura; la casella del costo va dal verde al rosso; numero rosso = sopra il mercato.": "· ਖੇਤ ਸਭ ਤੋਂ ਵਧੀਆ ਤੋਂ ਸਭ ਤੋਂ ਮਾੜੇ ਤੱਕ, ਉਤਪਾਦਾਂ ਦੇ ਪ੍ਰਤੀ ਇਕਾਈ ਖ਼ਰਚੇ ਨੂੰ ਬਾਜ਼ਾਰੀ ਭਾਅ ਨਾਲ ਮਿਲਾ ਕੇ (ਉਤਪਾਦ ਵੱਖਰੇ ਹਨ)। ਖੇਤ ਦਾ ਰੰਗ ਫ਼ਸਲ ਹੈ; ਖ਼ਰਚੇ ਦਾ ਖ਼ਾਨਾ ਹਰੇ ਤੋਂ ਲਾਲ ਤੱਕ; ਲਾਲ ਅੰਕ = ਬਾਜ਼ਾਰ ਤੋਂ ਉੱਪਰ।",
"· I campi su tutte le stagioni. Ogni campo è confrontato con gli altri della stessa coltura nella stessa stagione: 100 = media dell'azienda, 150 = una volta e mezza. La sulla, unica, è confrontata con la medica.": "· ਸਾਰੇ ਸੀਜ਼ਨਾਂ ਦੇ ਖੇਤ। ਹਰ ਖੇਤ ਦੀ ਤੁਲਨਾ ਉਸੇ ਸੀਜ਼ਨ ਵਿੱਚ ਉਸੇ ਫ਼ਸਲ ਵਾਲੇ ਹੋਰ ਖੇਤਾਂ ਨਾਲ: 100 = ਫ਼ਾਰਮ ਦੀ ਔਸਤ, 150 = ਡੇਢ ਗੁਣਾ। ਸੁੱਲਾ, ਜੋ ਇਕੱਲੀ ਹੈ, ਲੂਸਣ ਨਾਲ ਮਿਲਾਈ ਜਾਂਦੀ ਹੈ।",
"· I totali della campagna per coltura: ettari, giornate di lavoro e quantità raccolte. Si compila da solo con i dati inseriti nei campi.": "· ਫ਼ਸਲ ਮੁਤਾਬਕ ਸੀਜ਼ਨ ਦਾ ਕੁੱਲ: ਹੈਕਟੇਅਰ, ਕੰਮ ਦੇ ਦਿਨ ਅਤੇ ਵੱਢੀ ਮਾਤਰਾ। ਖੇਤਾਂ ਵਿੱਚ ਭਰੇ ਡਾਟੇ ਨਾਲ ਆਪਣੇ ਆਪ ਭਰਦਾ ਹੈ।",
"· Il programma di semina e concimazione della campagna scelta sopra: per ogni campo cosa si semina e si concima, la dose per ettaro e la quantità totale, con le istruzioni. In «Da acquistare» la lista dei semi e dei concimi da comprare. È un piano: quando si esegue un lavoro si registra nella scheda del campo.": "· ਉੱਪਰ ਚੁਣੇ ਸੀਜ਼ਨ ਦੀ ਬਿਜਾਈ ਅਤੇ ਖਾਦ ਯੋਜਨਾ: ਹਰ ਖੇਤ ਵਿੱਚ ਕੀ ਬੀਜਣਾ ਅਤੇ ਕਿਹੜੀ ਖਾਦ, ਪ੍ਰਤੀ ਹੈਕਟੇਅਰ ਮਾਤਰਾ ਅਤੇ ਕੁੱਲ ਮਾਤਰਾ, ਹਦਾਇਤਾਂ ਸਮੇਤ। «ਖ਼ਰੀਦਣਾ ਹੈ» ਵਿੱਚ ਖ਼ਰੀਦਣ ਵਾਲੇ ਬੀਜਾਂ ਅਤੇ ਖਾਦਾਂ ਦੀ ਸੂਚੀ। ਇਹ ਯੋਜਨਾ ਹੈ: ਕੰਮ ਹੋਣ ਤੇ ਖੇਤ ਦੇ ਰਿਕਾਰਡ ਵਿੱਚ ਦਰਜ ਕਰੋ।",
"· L'elenco dei campi. Tocca un campo per aprire la sua scheda e registrare semina, lavorazioni, concimazioni e raccolta della campagna scelta sopra.": "· ਖੇਤਾਂ ਦੀ ਸੂਚੀ। ਖੇਤ ਦਬਾ ਕੇ ਉਸਦਾ ਰਿਕਾਰਡ ਖੋਲ੍ਹੋ ਅਤੇ ਉੱਪਰ ਚੁਣੇ ਸੀਜ਼ਨ ਦੀ ਬਿਜਾਈ, ਖੇਤ ਦੇ ਕੰਮ, ਖਾਦ ਅਤੇ ਵਾਢੀ ਦਰਜ ਕਰੋ।",
"· Quanto è costato ogni prodotto della campagna, il confronto con il prezzo di mercato e con le rese di riferimento, e dove si perde o si guadagna. Tocca una coltura per vedere i suoi campi.": "· ਸੀਜ਼ਨ ਦੇ ਹਰ ਉਤਪਾਦ ਦਾ ਖ਼ਰਚਾ, ਬਾਜ਼ਾਰੀ ਭਾਅ ਅਤੇ ਹਵਾਲਾ ਝਾੜ ਨਾਲ ਤੁਲਨਾ, ਅਤੇ ਕਿੱਥੇ ਘਾਟਾ ਜਾਂ ਮੁਨਾਫ਼ਾ ਹੈ। ਖੇਤ ਦੇਖਣ ਲਈ ਫ਼ਸਲ ਦਬਾਓ।",
"· Scegli un campo: stagione per stagione coltura, produzione, costi, concimi usati con la dose per ettaro, e il risultato contro il mercato.": "· ਖੇਤ ਚੁਣੋ: ਸੀਜ਼ਨ-ਦਰ-ਸੀਜ਼ਨ ਫ਼ਸਲ, ਪੈਦਾਵਾਰ, ਖ਼ਰਚੇ, ਪ੍ਰਤੀ ਹੈਕਟੇਅਰ ਮਾਤਰਾ ਨਾਲ ਵਰਤੀਆਂ ਖਾਦਾਂ, ਅਤੇ ਬਾਜ਼ਾਰ ਦੇ ਮੁਕਾਬਲੇ ਨਤੀਜਾ।",
"· Scegli una coltura: i campi che l'hanno avuta, dal migliore al peggiore, sommando tutte le stagioni. Conta quanto è costato il prodotto rispetto al suo valore di mercato; costo e mercato sono al quintale del prodotto principale. Numero rosso = sopra il mercato.": "· ਫ਼ਸਲ ਚੁਣੋ: ਜਿਨ੍ਹਾਂ ਖੇਤਾਂ ਵਿੱਚ ਇਹ ਸੀ, ਸਭ ਤੋਂ ਵਧੀਆ ਤੋਂ ਮਾੜੇ ਤੱਕ, ਸਾਰੇ ਸੀਜ਼ਨ ਜੋੜ ਕੇ। ਮਾਇਨੇ ਰੱਖਦਾ ਹੈ ਕਿ ਉਤਪਾਦ ਦਾ ਖ਼ਰਚਾ ਉਸਦੇ ਬਾਜ਼ਾਰੀ ਮੁੱਲ ਦੇ ਮੁਕਾਬਲੇ ਕਿੰਨਾ ਸੀ; ਖ਼ਰਚਾ ਅਤੇ ਬਾਜ਼ਾਰ ਮੁੱਖ ਉਤਪਾਦ ਦੇ ਪ੍ਰਤੀ ਕੁਇੰਟਲ ਹਨ। ਲਾਲ ਅੰਕ = ਬਾਜ਼ਾਰ ਤੋਂ ਉੱਪਰ।",
"· Scegli una coltura: per ogni stagione ettari, resa, costo e quanto è costata ogni unità di prodotto contro il prezzo di mercato. In rosso i costi sopra il mercato.": "· ਫ਼ਸਲ ਚੁਣੋ: ਹਰ ਸੀਜ਼ਨ ਲਈ ਹੈਕਟੇਅਰ, ਝਾੜ, ਖ਼ਰਚਾ ਅਤੇ ਬਾਜ਼ਾਰੀ ਭਾਅ ਦੇ ਮੁਕਾਬਲੇ ਹਰ ਇਕਾਈ ਦਾ ਖ਼ਰਚਾ। ਬਾਜ਼ਾਰ ਤੋਂ ਉੱਪਰ ਦੇ ਖ਼ਰਚੇ ਲਾਲ ਵਿੱਚ।",
"· Tutte le stagioni caricate, affiancate: superficie, costo per ettaro, saldo contro il mercato e produzione dei prodotti.": "· ਸਾਰੇ ਲੋਡ ਕੀਤੇ ਸੀਜ਼ਨ ਨਾਲ-ਨਾਲ: ਰਕਬਾ, ਪ੍ਰਤੀ ਹੈਕਟੇਅਰ ਖ਼ਰਚਾ, ਬਾਜ਼ਾਰ ਦੇ ਮੁਕਾਬਲੇ ਬਕਾਇਆ ਅਤੇ ਪੈਦਾਵਾਰ।",
"· Tutte le stagioni insieme: costi e rese per coltura, la storia di ogni campo con la concimazione, la classifica dei campi per stagione e per resa. Non dipende dalla campagna scelta sopra e si aggiorna da solo con le nuove stagioni.": "· ਸਾਰੇ ਸੀਜ਼ਨ ਇਕੱਠੇ: ਫ਼ਸਲ ਮੁਤਾਬਕ ਖ਼ਰਚੇ ਅਤੇ ਝਾੜ, ਹਰ ਖੇਤ ਦਾ ਖਾਦ ਸਮੇਤ ਇਤਿਹਾਸ, ਸੀਜ਼ਨ ਅਤੇ ਝਾੜ ਮੁਤਾਬਕ ਖੇਤਾਂ ਦੀ ਦਰਜਾਬੰਦੀ। ਉੱਪਰ ਚੁਣੇ ਸੀਜ਼ਨ ਤੇ ਨਿਰਭਰ ਨਹੀਂ ਅਤੇ ਨਵੇਂ ਸੀਜ਼ਨਾਂ ਨਾਲ ਆਪਣੇ ਆਪ ਅੱਪਡੇਟ ਹੁੰਦਾ ਹੈ।",
