"Ranking genetico: IIP, produttività, età primo parto, resa media figli": "ਜੈਨੇਟਿਕ ਦਰਜਾਬੰਦੀ: ਸੂਣ ਦਾ ਵਕਫ਼ਾ, ਉਤਪਾਦਕਤਾ, ਪਹਿਲੇ ਸੂਏ ਦੀ ਉਮਰ, ਔਲਾਦ ਦਾ ਔਸਤ ਝਾੜ",
"📤 Uscite": "📤 ਨਿਕਾਸੀ",
