"📥 Esporta": "📥 ਐਕਸਪੋਰਟ",
"Export Excel granulare — anagrafica, uscite, UBA, consanguineità": "ਵਿਸਤਾਰ ਵਾਲਾ Excel ਐਕਸਪੋਰਟ — ਰਜਿਸਟਰ, ਨਿਕਾਸੀ, ਪਸ਼ੂ ਇਕਾਈ, ਨੇੜਲੀ ਰਿਸ਼ਤੇਦਾਰੀ",
