  "⚠️ Scegliere il motivo dell'uscita.": "⚠️ ਬਾਹਰ ਜਾਣ ਦਾ ਕਾਰਨ ਚੁਣੋ।",
  "⚠️ Inserire la data.": "⚠️ ਤਾਰੀਖ਼ ਲਿਖੋ।",
  "⚠️ Scegliere la causa della morte.": "⚠️ ਮੌਤ ਦੀ ਵਜ੍ਹਾ ਚੁਣੋ।",
  "⚠️ Scrivere quale malattia nella casella «Causa».": "⚠️ «ਵਜ੍ਹਾ» ਖ਼ਾਨੇ ਵਿੱਚ ਲਿਖੋ ਕਿਹੜੀ ਬਿਮਾਰੀ ਸੀ।",
  "⚠️ Con «Altro» va specificato il motivo dell'uscita.": "⚠️ «ਹੋਰ» ਚੁਣਨ ਤੇ ਬਾਹਰ ਜਾਣ ਦਾ ਕਾਰਨ ਲਿਖਣਾ ਜ਼ਰੂਰੀ ਹੈ।",
