  "⚖️ «Sesso e peso»: 🔴 sesso obbligatorio (maschio, femmina, castrato) e peso alla nascita, o in entrata per gli acquistati. Se il sesso manca il pulsante è rosso e dice «MANCA IL SESSO». Se scegli «Castrato» va inserita la data della castrazione: l'app registra anche l'evento «Castrazione» nel registro sanitario": "⚖️ «ਲਿੰਗ ਅਤੇ ਭਾਰ»: 🔴 ਲਿੰਗ ਜ਼ਰੂਰੀ ਹੈ (ਨਰ, ਮਾਦਾ, ਖੱਸੀ) ਅਤੇ ਜਨਮ ਦਾ ਭਾਰ, ਜਾਂ ਖ਼ਰੀਦੇ ਸੂਰਾਂ ਲਈ ਆਉਣ ਸਮੇਂ ਦਾ ਭਾਰ। ਜੇ ਲਿੰਗ ਨਹੀਂ ਹੈ ਤਾਂ ਬਟਨ ਲਾਲ ਹੈ ਅਤੇ «ਲਿੰਗ ਨਹੀਂ ਹੈ» ਲਿਖਿਆ ਹੈ। ਜੇ «ਖੱਸੀ» ਚੁਣੋ ਤਾਂ ਖੱਸੀ ਕਰਨ ਦੀ ਤਾਰੀਖ਼ ਲਿਖਣੀ ਜ਼ਰੂਰੀ ਹੈ: ਐਪ ਸਿਹਤ ਰਜਿਸਟਰ ਵਿੱਚ «ਖੱਸੀ ਕਰਨਾ» ਘਟਨਾ ਵੀ ਦਰਜ ਕਰਦੀ ਹੈ",
  "All'apertura della sezione 🐷 Lotti compare l'avviso rosso «⚠️ REGISTRARE IL SESSO E LE MORTI DEI SUINETTI», con il numero di suinetti vivi ancora senza sesso. Tocca «Ho capito» e completa: sesso con ⚖️, morte con 📤 (motivo «Morto»). Nello stesso avviso compaiono le scrofe «DA MANDARE AL MACELLO».": "🐷 ਲਾਟ ਭਾਗ ਖੋਲ੍ਹਣ ਤੇ ਲਾਲ ਸੁਨੇਹਾ «⚠️ ਬੱਚਿਆਂ ਦਾ ਲਿੰਗ ਅਤੇ ਮੌਤਾਂ ਦਰਜ ਕਰੋ» ਆਉਂਦਾ ਹੈ, ਜਿਸ ਵਿੱਚ ਬਿਨਾਂ ਲਿੰਗ ਵਾਲੇ ਜਿਉਂਦੇ ਬੱਚਿਆਂ ਦੀ ਗਿਣਤੀ ਹੁੰਦੀ ਹੈ। «ਸਮਝ ਗਿਆ» ਦਬਾਓ ਅਤੇ ਪੂਰਾ ਕਰੋ: ਲਿੰਗ ⚖️ ਨਾਲ, ਮੌਤ 📤 ਨਾਲ (ਕਾਰਨ «ਮਰਿਆ»)। ਇਸੇ ਸੁਨੇਹੇ ਵਿੱਚ «ਬੁੱਚੜਖ਼ਾਨੇ ਭੇਜਣੀ ਹੈ» ਵਾਲੀਆਂ ਸੂਰਨੀਆਂ ਵੀ ਆਉਂਦੀਆਂ ਹਨ।",
  "✂ Castrazione dei maschi": "✂ ਨਰਾਂ ਨੂੰ ਖੱਸੀ ਕਰਨਾ",
  "Un solo suinetto: ⚖️ «Sesso e peso» → sesso «Castrato» → data della castrazione → Salva": "ਇੱਕ ਬੱਚਾ: ⚖️ «ਲਿੰਗ ਅਤੇ ਭਾਰ» → ਲਿੰਗ «ਖੱਸੀ» → ਖੱਸੀ ਕਰਨ ਦੀ ਤਾਰੀਖ਼ → ਸੇਵ ਕਰੋ",
  "Tutti i maschi del lotto insieme: nella scheda del lotto tocca «✂ Castra tutti i maschi (N)», controlla la data (di base oggi) e conferma. Vengono castrati solo i maschi vivi ancora non castrati": "ਲਾਟ ਦੇ ਸਾਰੇ ਨਰ ਇਕੱਠੇ: ਲਾਟ ਦੇ ਕਾਰਡ ਵਿੱਚ «✂ ਸਾਰੇ ਨਰ ਖੱਸੀ ਕਰੋ (N)» ਦਬਾਓ, ਤਾਰੀਖ਼ ਵੇਖੋ (ਪਹਿਲਾਂ ਤੋਂ ਅੱਜ ਦੀ) ਅਤੇ ਪੱਕਾ ਕਰੋ। ਸਿਰਫ਼ ਉਹ ਜਿਉਂਦੇ ਨਰ ਖੱਸੀ ਹੁੰਦੇ ਹਨ ਜੋ ਅਜੇ ਖੱਸੀ ਨਹੀਂ ਹਨ",
