  "🔴 Registrare SEMPRE la morte e la sua causa, il giorno stesso. Le morti «Schiacciato dalla madre» e «Ucciso dalla madre» compaiono anche nella scheda della madre, per la selezione. Una scrofa che ha ucciso anche 1 solo suinetto, oppure ne ha schiacciati 2 o più (sommando parti diversi), viene segnalata in rosso «DA MANDARE AL MACELLO» nella sua scheda e nell'avviso dei Lotti.": "🔴 ਮੌਤ ਅਤੇ ਉਸਦੀ ਵਜ੍ਹਾ ਹਮੇਸ਼ਾ ਉਸੇ ਦਿਨ ਦਰਜ ਕਰੋ। «ਮਾਂ ਹੇਠਾਂ ਦੱਬ ਕੇ ਮਰਿਆ» ਅਤੇ «ਮਾਂ ਨੇ ਮਾਰਿਆ» ਵਾਲੀਆਂ ਮੌਤਾਂ ਚੋਣ ਲਈ ਮਾਂ ਦੇ ਕਾਰਡ ਵਿੱਚ ਵੀ ਆਉਂਦੀਆਂ ਹਨ। ਜਿਸ ਸੂਰਨੀ ਨੇ 1 ਬੱਚਾ ਵੀ ਮਾਰਿਆ ਹੈ, ਜਾਂ 2 ਜਾਂ ਵੱਧ ਦੱਬ ਕੇ ਮਾਰੇ ਹਨ (ਵੱਖ-ਵੱਖ ਸੂਣਾਂ ਜੋੜ ਕੇ), ਉਹ ਆਪਣੇ ਕਾਰਡ ਵਿੱਚ ਅਤੇ ਲਾਟ ਦੇ ਸੁਨੇਹੇ ਵਿੱਚ ਲਾਲ ਰੰਗ ਵਿੱਚ «ਬੁੱਚੜਖ਼ਾਨੇ ਭੇਜਣੀ ਹੈ» ਦਿਖਾਈ ਜਾਂਦੀ ਹੈ।",
  "Scegli il motivo: Macellato, Morto, Venduto vivo o Altro. Con «Morto» segui i passi della sezione «✝️ Morte di un suinetto». Con «Altro» è obbligatorio scrivere il motivo nella casella «Specificare il motivo»": "ਕਾਰਨ ਚੁਣੋ: ਬੁੱਚੜਖ਼ਾਨੇ ਗਿਆ, ਮਰਿਆ, ਜਿਉਂਦਾ ਵੇਚਿਆ ਜਾਂ ਹੋਰ। «ਮਰਿਆ» ਨਾਲ «✝️ ਬੱਚੇ ਦੀ ਮੌਤ» ਭਾਗ ਦੇ ਕਦਮ ਮੰਨੋ। «ਹੋਰ» ਨਾਲ «ਕਾਰਨ ਲਿਖੋ» ਖ਼ਾਨੇ ਵਿੱਚ ਕਾਰਨ ਲਿਖਣਾ ਜ਼ਰੂਰੀ ਹੈ",
